import urllib.request
import json
import sys

SUPABASE_URL = "https://lfloyhdkrvpfgvvlppah.supabase.co"
SUPABASE_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImxmbG95aGRrcnZwZmd2dmxwcGFoIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk3Nzk0NTQsImV4cCI6MjEwNTM1NTQ1NH0.Kpme7uzC6xy69HMr31X57AGJTDpYKuJiwweoXhmjZWQ"

headers = {
    "apikey": SUPABASE_KEY,
    "Authorization": f"Bearer {SUPABASE_KEY}",
    "Content-Type": "application/json",
    "Prefer": "return=representation"
}

def get_existing_tickets():
    url = f"{SUPABASE_URL}/rest/v1/tickets?select=*&order=id.asc"
    req = urllib.request.Request(url, headers=headers, method="GET")
    try:
        with urllib.request.urlopen(req) as resp:
            return json.loads(resp.read().decode("utf-8"))
    except Exception as e:
        print("Error fetching existing tickets:", e)
        return []

def add_more_tickets(count_to_add):
    existing = get_existing_tickets()
    print("==========================================================")
    print(f"Current Total Tickets in Database: {len(existing)}")
    
    max_num = 0
    for t in existing:
        code = t.get("code", "")
        if code.startswith("MOIST-VIP-"):
            try:
                num = int(code.replace("MOIST-VIP-", ""))
                if num > max_num:
                    max_num = num
            except ValueError:
                pass
        if t.get("id", 0) > max_num:
            max_num = t.get("id")

    start_num = max_num + 1
    end_num = max_num + count_to_add

    print(f"Adding {count_to_add} new VIP tickets: MOIST-VIP-{start_num:03d} to MOIST-VIP-{end_num:03d}...")
    print("==========================================================")

    new_tickets = []
    for i in range(start_num, end_num + 1):
        code_str = f"MOIST-VIP-{i:03d}"
        new_tickets.append({
            "code": code_str,
            "is_claimed": False,
            "claimed_at": None
        })

    url = f"{SUPABASE_URL}/rest/v1/tickets"
    data = json.dumps(new_tickets).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")

    try:
        with urllib.request.urlopen(req) as resp:
            added_data = json.loads(resp.read().decode("utf-8"))
            print(f"SUCCESSFULLY ADDED {len(added_data)} NEW VIP TICKETS!")
            print(f"Total Tickets Now in Database: {len(existing) + len(added_data)}")
            print("==========================================================")
            for t in added_data:
                print(f"  + New Ticket Code: {t['code']} | Claimed: {t['is_claimed']}")
            print("==========================================================")
    except Exception as e:
        print("Error adding new tickets:", e)

if __name__ == "__main__":
    count = None
    if len(sys.argv) > 1:
        try:
            count = int(sys.argv[1])
        except ValueError:
            pass

    if count is None:
        try:
            user_input = input("How many additional VIP tickets do you want to add? ")
            count = int(user_input.strip())
        except Exception:
            print("Invalid input. Exiting.")
            sys.exit(1)

    if count <= 0:
        print("Number of tickets to add must be greater than 0.")
        sys.exit(1)

    add_more_tickets(count)
